import os
import signal
from pathlib import Path
root = 3189744
root_path = Path(f'/proc/{root}')
if root_path.exists():
    command = (root_path / 'cmdline').read_bytes().replace(b'\\0', b' ').decode()
    if 'lake build MIPStarRE.QPBT' not in command:
        raise SystemExit(f'Refusing to stop unexpected process: {command}')
    descendants = {root}
    parents = {}
    for path in Path('/proc').iterdir():
        if path.name.isdigit():
            try:
                status = (path / 'status').read_text()
                parents[int(path.name)] = int(next(line.split()[1] for line in status.splitlines() if line.startswith('PPid:')))
            except (OSError, StopIteration):
                pass
    while True:
        expanded = descendants | {pid for pid, parent in parents.items() if parent in descendants}
        if expanded == descendants:
            break
        descendants = expanded
    for pid in sorted(descendants - {root}, reverse=True) + [root]:
        try:
            os.kill(pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
    print('Stopped only this publication gate build:', sorted(descendants))
else:
    print('Publication gate build already finished.')
